// Create a null time and validate basic properties
struct icaltimetype tt = icaltime_null_time();
// Property: a null time should be reported as null
FUZZ_ASSERT(icaltime_is_null_time(tt), "icaltime_null_time() must produce a null time");
// It may or may not be a DATE; just exercise formatting and validation paths
(void)icaltime_is_valid_time(tt);
(const char *)icaltime_as_ical_string(tt);

// Create a null date and validate it indicates a DATE
struct icaltimetype d = icaltime_null_date();
