    setVObjectIntegerValue(o, *FUZZ_PARAM(unsigned int));
} else if (pick == 3) {
    setVObjectLongValue(o, *FUZZ_PARAM(unsigned long));
} else if (pick == 4) {
    setVObjectAnyValue(o, (void *)0);
} else /* pick == 5 */ {
    std::string cid = FUZZ_PARAM_STR();
    VObject *child = newVObject(cid.c_str());
    if (!child) { FUZZ_BAIL(); }
    // Attach nested VObject; parent now owns child
    setVObjectVObjectValue(o, child);
    FUZZ_SET_ATTR_PTR(child, "parent", o);
    FUZZ_SET_ATTR_STR(child, "owner", "attached");
}
int t = vObjectValueType((const VObject *)o);
(void)t;
// Return o for further actions
// Validation: exercised multiple setter paths and queried the resulting type code; ownership rules observed for nested VOBJECT.

// Open a writable file stream and pretty-print the VObject to it
const char *fname = FUZZ_PARAM_FILENAME();
FILE *fp = fopen(fname, "wb");
if (!fp) { FUZZ_BAIL(); }
printVObject(fp, o);
// Close stream promptly to avoid resource leaks
fclose(fp);
// Return object; printing does not alter ownership
// Validation: exercised FILE*-based pretty-printer with safe open/close semantics.

// Open a writable file stream and write the VObject in canonical format
const char *fname = FUZZ_PARAM_FILENAME();
FILE *fp = fopen(fname, "wb");
if (!fp) { FUZZ_BAIL(); }
writeVObject(fp, o);
fclose(fp);
// Return object for continued fuzzing
