// Allocate and populate an icalvcal_defaults with safe, NUL-terminated strings
icalvcal_defaults *defaults = new icalvcal_defaults;
if (!defaults) { FUZZ_BAIL(); }

// Generate bounded strings (<=1024 bytes) for all three fields
std::string s_url = FUZZ_PARAM_STR();
std::string s_fmt = FUZZ_PARAM_STR();
std::string s_desc = FUZZ_PARAM_STR();
size_t n_url = s_url.size(); if (n_url > 1023) n_url = 1023;
size_t n_fmt = s_fmt.size(); if (n_fmt > 1023) n_fmt = 1023;
size_t n_desc = s_desc.size(); if (n_desc > 1023) n_desc = 1023;

char *buf_url = new char[n_url + 1]; if (!buf_url) { delete defaults; FUZZ_BAIL(); }
char *buf_fmt = new char[n_fmt + 1]; if (!buf_fmt) { delete[] buf_url; delete defaults; FUZZ_BAIL(); }
char *buf_desc = new char[n_desc + 1]; if (!buf_desc) { delete[] buf_fmt; delete[] buf_url; delete defaults; FUZZ_BAIL(); }

memcpy(buf_url, s_url.data(), n_url); buf_url[n_url] = '\0';
memcpy(buf_fmt, s_fmt.data(), n_fmt); buf_fmt[n_fmt] = '\0';
memcpy(buf_desc, s_desc.data(), n_desc); buf_desc[n_desc] = '\0';

defaults->alarm_audio_url = buf_url;
defaults->alarm_audio_fmttype = buf_fmt;
defaults->alarm_description = buf_desc;

// Track attributes for downstream stubs
FUZZ_SET_ATTR_INT(defaults, "has_url", 1);
FUZZ_SET_ATTR_INT(defaults, "has_fmt", 1);
FUZZ_SET_ATTR_INT(defaults, "has_desc", 1);

// Validation: constructed non-null defaults with three valid C strings suitable for icalvcal conversion.

