import random
import string
from typing import List

# Generator for iCalendar duration strings per RFC 5545
# Forms to cover:
# - PnW
# - PnD
# - PTnH / PTnM / PTnS
# - PnDTnHnMnS (any subset as long as at least one time designator if T present)
# - Optional sign + or -
# - Zero duration: P0D or PT0S
# We keep values within reasonable bounds, but include some extremes to trigger edge cases.

_DEF_WEIGHTS = {
    "W": 1,
    "D": 2,
    "T": 3,
    "TD": 4,   # date + time
    "TIME": 5, # time-only
    "ZERO": 1,
}

def _rand_int(rnd: random.Random, low: int, high: int) -> int:
    return rnd.randint(low, high)

def _choose(rnd: random.Random, items: List):
    return items[rnd.randrange(len(items))]

def _maybe_sign(rnd: random.Random) -> str:
    return _choose(rnd, ["", "+", "-"])

def _pick_edge_number(rnd: random.Random, typical_low: int, typical_high: int) -> int:
    # Include some interesting magnitudes
    candidates = [0, 1, 2, 59, 60, 61, 999999, _rand_int(rnd, typical_low, typical_high)]
    return _choose(rnd, candidates)

def _gen_weeks(rnd: random.Random) -> str:
    n = _pick_edge_number(rnd, 1, 104)  # up to 2 years of weeks
    return f"P{n}W"

def _gen_days_only(rnd: random.Random) -> str:
    n = _pick_edge_number(rnd, 1, 3650)  # up to 10 years
    return f"P{n}D"

def _gen_time_only(rnd: random.Random) -> str:
    # Must have at least one of H/M/S
    parts = []
    # Randomly decide which units to include; at least one
    include_h = rnd.random() < 0.6
    include_m = rnd.random() < 0.8 or not include_h
    include_s = rnd.random() < 0.8 or (not include_h and not include_m)
    if include_h:
        parts.append(f"{_pick_edge_number(rnd, 0, 48)}H")
    if include_m:
        parts.append(f"{_pick_edge_number(rnd, 0, 200)}M")
    if include_s:
        parts.append(f"{_pick_edge_number(rnd, 0, 200)}S")
    # Ensure at least one
    if not parts:
        parts.append(f"{_pick_edge_number(rnd, 0, 200)}S")
    return "P" + "T" + "".join(parts)

def _gen_date_time(rnd: random.Random) -> str:
    # P<n>D T <h><m><s> with optional each part, but at least one time unit if T present
    d = _pick_edge_number(rnd, 0, 3650)
    date = f"{d}D" if rnd.random() < 0.9 else ""  # sometimes omit days
    # time parts
    parts = []
    if rnd.random() < 0.7:
        parts.append(f"{_pick_edge_number(rnd, 0, 48)}H")
    if rnd.random() < 0.85 or not parts:
        parts.append(f"{_pick_edge_number(rnd, 0, 200)}M")
    if rnd.random() < 0.85 or not parts:
        parts.append(f"{_pick_edge_number(rnd, 0, 200)}S")
    # Guarantee at least one time part
    if not parts:
        parts.append(f"{_pick_edge_number(rnd, 0, 200)}S")
    return "P" + date + "T" + "".join(parts)

def _gen_zero(rnd: random.Random) -> str:
    return _choose(rnd, ["P0D", "PT0S"])

def _gen_duration_string(rnd: random.Random) -> str:
    kind = rnd.choices(list(_DEF_WEIGHTS.keys()), weights=list(_DEF_WEIGHTS.values()), k=1)[0]
    core = ""
    if kind == "W":
        core = _gen_weeks(rnd)
    elif kind == "D":
        core = _gen_days_only(rnd)
    elif kind == "TIME":
        core = _gen_time_only(rnd)
    elif kind == "TD":
        # Randomly choose date+time or date without time T (rare but we keep T for coverage)
        core = _gen_date_time(rnd)
    elif kind == "T":
        core = _gen_time_only(rnd)
    elif kind == "ZERO":
        core = _gen_zero(rnd)
    else:
        core = _gen_time_only(rnd)

    sign = _maybe_sign(rnd)
    # Place sign at start if present
    return sign + core

def _maybe_whitespace_wrap(rnd: random.Random, s: str) -> str:
    # Some callers may trim; include simple whitespace occasionally but keep valid
    if rnd.random() < 0.15:
        left = "".join(rnd.choice(["", " ", "\t"]) for _ in range(rnd.randint(0, 2)))
        right = "".join(rnd.choice(["", " ", "\t"]) for _ in range(rnd.randint(0, 2)))
        return left + s + right
    return s

def _maybe_lowercase(rnd: random.Random, s: str) -> str:
    # RFC tokens are uppercase; some parsers accept lowercase. Randomly lower/keep.
    if rnd.random() < 0.2:
        return s.lower()
    return s

def generate(seed: int) -> bytes:
    rnd = random.Random(seed)

    # Generate a small set of candidate valid durations and pick one,
    # to add variety across calls with same seed by advancing PRNG.
    candidates = []
    count = rnd.randint(3, 7)
    for _ in range(count):
        s = _gen_duration_string(rnd)
        s = _maybe_whitespace_wrap(rnd, s)
        s = _maybe_lowercase(rnd, s)
        candidates.append(s)
    out = _choose(rnd, candidates)

    # Ensure size limit
    if len(out) > 4096:
        out = out[:4096]
    return out.encode("utf-8")

import random
import string
from typing import List, Tuple

# This generator emits valid iCalendar data for libical fuzz stubs that
# consume either:
#  - a full VCALENDAR text (icalparser_parse_string)
#  - a single property content line (icalproperty_new_from_string)
#  - a filename whose file will be populated by the harness with our bytes
#    (icalset_new_file*, icalfileset_new*). For those, we generate complete
#    VCALENDAR data so opening as a file-backed set is plausible.
#
# The function returns a bytes object (<= 4096 bytes) that is an interesting
# and valid iCalendar payload. Randomness is seeded by the input seed.

CRLF = "\r\n"

# A small corpus of valid property names libical recognizes.
PROPERTY_KINDS = [
    "PRODID",
    "VERSION",
    "CALSCALE",
    "METHOD",
    "BEGIN",
    "END",
    # Component-common properties
    "UID",
    "DTSTAMP",
    "DTSTART",
    "DTEND",
    "DUE",
    "DURATION",
    "SUMMARY",
    "DESCRIPTION",
    "LOCATION",
    "RRULE",
    "RDATE",
    "EXDATE",
    "STATUS",
    "SEQUENCE",
    "PRIORITY",
    "TRANSP",
    "ATTENDEE",
    "ORGANIZER",
    "CATEGORIES",
    "CLASS",
    "GEO",
    "URL",
]

WEEKDAYS = ["MO", "TU", "WE", "TH", "FR", "SA", "SU"]

STATUSES_EVENT = ["TENTATIVE", "CONFIRMED", "CANCELLED"]
STATUSES_TODO = ["NEEDSACTION", "COMPLETED", "INPROCESS", "CANCELLED"]
TRANSP_VALUES = ["OPAQUE", "TRANSPARENT"]
CLASSES = ["PUBLIC", "PRIVATE", "CONFIDENTIAL"]

TZIDS = [
    "UTC",
    "America/New_York",
    "Europe/Berlin",
    "Asia/Tokyo",
    "Pacific/Auckland",
]

PRODIDS = [
    "-//Example Corp//Libical Fuzz Gen//EN",
    "-//ACME Inc//Calendar 2.0//EN",
    "-//Test Suite//iCal Data//EN",
]

METHODS = ["PUBLISH", "REQUEST", "REPLY", "ADD", "CANCEL", "REFRESH", "COUNTER", "DECLINECOUNTER"]


def rand_choice(rng: random.Random, items: List[str]) -> str:
    return items[rng.randrange(0, len(items))]


def rand_token(rng: random.Random, alphabet: str, min_len: int, max_len: int) -> str:
    n = rng.randint(min_len, max_len)
    return "".join(rng.choice(alphabet) for _ in range(n))


def rand_text(rng: random.Random, min_len: int = 3, max_len: int = 24) -> str:
    # Basic TEXT per RFC 5545: allow letters, digits, spaces, some punctuation; escape commas/semis/backslashes
    raw = rand_token(rng, string.ascii_letters + string.digits + " -_./:", min_len, max_len)
    return raw.replace("\\", "\\\\").replace(",", "\\,").replace(";", "\\;")


def rand_uid(rng: random.Random) -> str:
    host = rand_token(rng, string.ascii_lowercase + string.digits, 6, 16) + ".example.com"
    local = rand_token(rng, string.ascii_lowercase + string.digits, 8, 16)
    return f"{local}@{host}"


def rand_date(rng: random.Random) -> Tuple[int, int, int]:
    year = rng.randint(1997, 2035)
    month = rng.randint(1, 12)
    # Simplify day selection to valid ranges
    days_in_month = [31, 29 if (year % 4 == 0 and (year % 100 != 0 or year % 400 == 0)) else 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31]
    day = rng.randint(1, days_in_month[month - 1])
    return year, month, day


def rand_time(rng: random.Random) -> Tuple[int, int, int]:
    return rng.randint(0, 23), rng.randint(0, 59), rng.randint(0, 59)


def fmt_date(y: int, m: int, d: int) -> str:
    return f"{y:04d}{m:02d}{d:02d}"


def fmt_datetime_utc(y: int, m: int, d: int, hh: int, mm: int, ss: int, with_z: bool = True) -> str:
    s = f"{y:04d}{m:02d}{d:02d}T{hh:02d}{mm:02d}{ss:02d}"
    return s + ("Z" if with_z else "")


def maybe_params_for_dt(rng: random.Random, tz_ok: bool = True) -> str:
    # Randomly add VALUE/TZID parameters
    parts = []
    if tz_ok and rng.random() < 0.5:
        parts.append(f"TZID={rand_choice(rng, TZIDS)}")
    if rng.random() < 0.2:
        parts.append("VALUE=DATE")
    return (";" + ";".join(parts)) if parts else ""


def make_rrule(rng: random.Random) -> str:
    freq = rand_choice(rng, ["DAILY", "WEEKLY", "MONTHLY", "YEARLY"]) if rng.random() < 0.8 else rand_choice(rng, ["SECONDLY", "MINUTELY", "HOURLY"])
    parts = [f"FREQ={freq}"]
    if rng.random() < 0.7:
        parts.append(f"INTERVAL={rng.randint(1, 6)}")
    if freq in ("WEEKLY", "MONTHLY", "YEARLY") and rng.random() < 0.7:
        byday_count = rng.randint(1, 3)
        byday = ",".join(rand_choice(rng, WEEKDAYS) for _ in range(byday_count))
        parts.append(f"BYDAY={byday}")
    if freq in ("MONTHLY", "YEARLY") and rng.random() < 0.5:
        parts.append(f"BYMONTHDAY={rng.randint(1,28)}")
    if freq == "YEARLY" and rng.random() < 0.5:
        parts.append(f"BYMONTH={rng.randint(1,12)}")
    if rng.random() < 0.5:
        count = rng.randint(2, 10)
        parts.append(f"COUNT={count}")
    return ";".join(parts)


def fold_line(line: str) -> str:
    # RFC 5545 folding at 75 octets; insert CRLF + space
    if len(line) <= 73:
        return line
    out = []
    i = 0
    first = True
    width = 73
    while i < len(line):
        chunk = line[i:i+width]
        if first:
            out.append(chunk)
            first = False
        else:
            out.append(CRLF + " " + chunk)
        i += width
        width = 73  # constant
    return "".join(out)


def make_property_line(name: str, value: str, params: str = "") -> str:
    # name[;PARAMS]:value CRLF with folding
    line = f"{name}{params}:{value}"
    return fold_line(line) + CRLF


def make_event(rng: random.Random) -> List[str]:
    lines = ["BEGIN:VEVENT" + CRLF]

    uid = rand_uid(rng)
    y, m, d = rand_date(rng)
    hh, mm, ss = rand_time(rng)

    # DTSTAMP UTC required by many tools
    lines.append(make_property_line("DTSTAMP", fmt_datetime_utc(y, m, d, hh, mm, ss, True)))

    # DTSTART
    if rng.random() < 0.25:
        # date-only event
        lines.append(make_property_line("DTSTART", fmt_date(y, m, d), params=";VALUE=DATE"))
    else:
        if rng.random() < 0.5:
            # UTC datetime
            lines.append(make_property_line("DTSTART", fmt_datetime_utc(y, m, d, hh, mm, ss, True)))
        else:
            # local with TZID
            params = f";TZID={rand_choice(rng, TZIDS)}"
            lines.append(make_property_line("DTSTART", fmt_datetime_utc(y, m, d, hh, mm, ss, False), params=params))

    # DTEND or DURATION
    if rng.random() < 0.6:
        # DTEND consistent with DTSTART
        y2, m2, d2 = y, m, d
        hh2, mm2, ss2 = (hh + rng.randint(0, 4)) % 24, (mm + rng.randint(0, 40)) % 60, ss
        if rng.random() < 0.25:
            lines.append(make_property_line("DTEND", fmt_date(y2, m2, d2), params=";VALUE=DATE"))
        else:
            if rng.random() < 0.5:
                lines.append(make_property_line("DTEND", fmt_datetime_utc(y2, m2, d2, hh2, mm2, ss2, True)))
            else:
                params = f";TZID={rand_choice(rng, TZIDS)}"
                lines.append(make_property_line("DTEND", fmt_datetime_utc(y2, m2, d2, hh2, mm2, ss2, False), params=params))
    else:
        # ISO8601 duration compatible with RFC5545
        dur = f"P{rng.randint(0,7)}W" if rng.random() < 0.3 else f"P{rng.randint(0,10)}DT{rng.randint(0,23)}H{rng.randint(0,59)}M{rng.randint(0,59)}S"
        lines.append(make_property_line("DURATION", dur))

    lines.append(make_property_line("UID", uid))
    lines.append(make_property_line("SUMMARY", rand_text(rng, 5, 40)))

    # Optional properties
    if rng.random() < 0.6:
        lines.append(make_property_line("LOCATION", rand_text(rng, 3, 30)))
    if rng.random() < 0.6:
        lines.append(make_property_line("DESCRIPTION", rand_text(rng, 10, 80)))
    if rng.random() < 0.5:
        lines.append(make_property_line("TRANSP", rand_choice(rng, TRANSP_VALUES)))
    if rng.random() < 0.4:
        lines.append(make_property_line("STATUS", rand_choice(rng, STATUSES_EVENT)))
    if rng.random() < 0.5:
        lines.append(make_property_line("SEQUENCE", str(rng.randint(0, 5))))
    if rng.random() < 0.5:
        lines.append(make_property_line("PRIORITY", str(rng.randint(0, 9))))
    if rng.random() < 0.5:
        lines.append(make_property_line("RRULE", make_rrule(rng)))
    if rng.random() < 0.3:
        # A couple of RDATEs (UTC)
        rds = []
        for _ in range(rng.randint(1, 3)):
            yx, mx, dx = rand_date(rng)
            hx, nx, sx = rand_time(rng)
            rds.append(fmt_datetime_utc(yx, mx, dx, hx, nx, sx, True))
        lines.append(make_property_line("RDATE", ",".join(rds)))

    lines.append("END:VEVENT" + CRLF)
    return lines


def make_todo(rng: random.Random) -> List[str]:
    lines = ["BEGIN:VTODO" + CRLF]
    uid = rand_uid(rng)
    y, m, d = rand_date(rng)
    hh, mm, ss = rand_time(rng)
    lines.append(make_property_line("DTSTAMP", fmt_datetime_utc(y, m, d, hh, mm, ss, True)))
    # DUE or DTSTART
    if rng.random() < 0.5:
        lines.append(make_property_line("DUE", fmt_datetime_utc(y, m, d, hh, mm, ss, True)))
    else:
        lines.append(make_property_line("DTSTART", fmt_datetime_utc(y, m, d, hh, mm, ss, True)))
    lines.append(make_property_line("UID", uid))
    lines.append(make_property_line("SUMMARY", rand_text(rng, 5, 40)))
    if rng.random() < 0.5:
        lines.append(make_property_line("STATUS", rand_choice(rng, STATUSES_TODO)))
    if rng.random() < 0.4:
        lines.append(make_property_line("PERCENT-COMPLETE", str(rng.randint(0, 100))))
    lines.append("END:VTODO" + CRLF)
    return lines


def make_vtimezone(rng: random.Random) -> List[str]:
    # A minimal VTIMEZONE with STANDARD subcomponent
    tzid = rand_choice(rng, TZIDS)
    lines = ["BEGIN:VTIMEZONE" + CRLF]
    lines.append(make_property_line("TZID", tzid))
    # Minimal standard/daylight blocks; keeping simple and valid
    lines.append("BEGIN:STANDARD" + CRLF)
    y, m, d = rand_date(rng)
    hh, mm, ss = rand_time(rng)
    lines.append(make_property_line("DTSTART", fmt_datetime_utc(y, m, d, hh, mm, ss, False)))
    lines.append(make_property_line("TZOFFSETFROM", "+0000"))
    lines.append(make_property_line("TZOFFSETTO", "+0000"))
    lines.append("END:STANDARD" + CRLF)
    lines.append("END:VTIMEZONE" + CRLF)
    return lines


def make_vcalendar(rng: random.Random) -> str:
    lines = []
    lines.append("BEGIN:VCALENDAR" + CRLF)
    lines.append(make_property_line("PRODID", rand_choice(rng, PRODIDS)))
    lines.append(make_property_line("VERSION", "2.0"))
    if rng.random() < 0.2:
        lines.append(make_property_line("CALSCALE", "GREGORIAN"))
    if rng.random() < 0.2:
        lines.append(make_property_line("METHOD", rand_choice(rng, METHODS)))

    # Optionally include a VTIMEZONE first to test timezone parsing
    if rng.random() < 0.4:
        lines.extend(make_vtimezone(rng))

    # Add one or more VEVENT/VTODO
    count = 1 + (0 if rng.random() < 0.6 else 1)
    for _ in range(count):
        if rng.random() < 0.75:
            lines.extend(make_event(rng))
        else:
            lines.extend(make_todo(rng))

    lines.append("END:VCALENDAR" + CRLF)
    cal = "".join(lines)
    # Ensure size bound
    if len(cal) > 4000:
        cal = cal[:4000]
        if not cal.endswith(CRLF):
            cal += CRLF
    return cal


def make_single_property_line(rng: random.Random) -> str:
    name = rand_choice(rng, PROPERTY_KINDS)
    # Value and parameters by property
    if name in ("DTSTART", "DTEND", "DUE", "DTSTAMP"):
        y, m, d = rand_date(rng)
        hh, mm, ss = rand_time(rng)
        if rng.random() < 0.3:
            params = ";VALUE=DATE"
            value = fmt_date(y, m, d)
        else:
            if rng.random() < 0.5:
                params = ""
                value = fmt_datetime_utc(y, m, d, hh, mm, ss, True)
            else:
                params = f";TZID={rand_choice(rng, TZIDS)}"
                value = fmt_datetime_utc(y, m, d, hh, mm, ss, False)
        return make_property_line(name, value, params=params)
    elif name == "DURATION":
        value = f"P{rng.randint(0,10)}DT{rng.randint(0,23)}H{rng.randint(0,59)}M{rng.randint(0,59)}S"
        return make_property_line(name, value)
    elif name == "RRULE":
        return make_property_line(name, make_rrule(rng))
    elif name == "RDATE":
        vals = []
        for _ in range(rng.randint(1, 3)):
            y, m, d = rand_date(rng)
            h, n, s = rand_time(rng)
            vals.append(fmt_datetime_utc(y, m, d, h, n, s, True))
        return make_property_line(name, ",".join(vals))
    elif name == "GEO":
        lat = f"{rng.uniform(-90,90):.6f}"
        lon = f"{rng.uniform(-180,180):.6f}"
        return make_property_line(name, f"{lat};{lon}")
    elif name == "STATUS":
        val = rand_choice(rng, STATUSES_EVENT + STATUSES_TODO)
        return make_property_line(name, val)
    elif name == "TRANSP":
        return make_property_line(name, rand_choice(rng, TRANSP_VALUES))
    elif name == "CLASS":
        return make_property_line(name, rand_choice(rng, CLASSES))
    elif name in ("PRODID", "SUMMARY", "DESCRIPTION", "LOCATION", "CATEGORIES"):
        return make_property_line(name, rand_text(rng, 5, 40))
    elif name in ("UID", "URL", "ORGANIZER", "ATTENDEE"):
        if name == "UID":
            return make_property_line(name, rand_uid(rng))
        if name == "URL":
            value = "https://" + rand_token(rng, string.ascii_lowercase + string.digits, 6, 12) + ".example.com/" + rand_token(rng, string.ascii_lowercase, 4, 10)
            return make_property_line(name, value)
        if name in ("ORGANIZER", "ATTENDEE"):
            # mailto URI with CN parameter sometimes
            addr = "mailto:" + rand_uid(rng)
            params = ";CN=" + rand_text(rng, 3, 12) if rng.random() < 0.5 else ""
            return make_property_line(name, addr, params=params)
    elif name in ("SEQUENCE", "PRIORITY"):
        return make_property_line(name, str(rng.randint(0, 10)))
    elif name in ("BEGIN", "END"):
        # For single property test, emit a valid component marker
        return make_property_line(name, rand_choice(rng, ["VCALENDAR", "VEVENT", "VTODO", "VTIMEZONE"]))

    # Fallback generic text
    return make_property_line(name, rand_text(rng, 5, 30))


def generate(seed: int) -> bytes:
    rng = random.Random(seed)

    # Choose among two main targets: a full VCALENDAR vs a single property line
    mode = rng.random()
    if mode < 0.65:
        payload = make_vcalendar(rng)
    else:
        payload = make_single_property_line(rng)
        # Ensure it's reasonably sized
        if len(payload) > 2048:
            payload = payload[:2048]
            if not payload.endswith(CRLF):
                payload += CRLF

    # Safety bound for harness limits (<= 4096 bytes)
    if len(payload) > 4096:
        payload = payload[:4096]
        if not payload.endswith(CRLF):
            payload += CRLF

    return payload.encode("utf-8")
